ST.xhtml:p:
RTring_GearIn(CLK := g_bGeneralAxis1GearInM OR g_bGeneralAxis1GearIn OR bGearIn);
RTring_GearOut(CLK := g_bGeneralAxis1GearOutM OR g_bGeneralAxis1GearOut OR bGearOut);

IF RTring_GearIn.Q THEN
  bGearIn := FALSE;
  g_bGeneralAxis1GearInM := FALSE;
  IF g_General1_Axis.NCTOPLC.AXISSTATE <> 8 THEN
    nGearstate := 1;
    g_boGeneralAxis1GearDone := FALSE;
    g_bGeneralAxis1GearDone := FALSE;
    bGearDone := FALSE;
  END_IF;
END_IF;
IF RTring_GearOut.Q THEN
  bGearOut := FALSE;
  g_bGeneralAxis1GearOutM := FALSE;
  IF g_General1_Axis.NCTOPLC.AXISSTATE = 8 THEN
    nGearstate := 2;
     g_boGeneralAxis1GearDone := FALSE;
    g_bGeneralAxis1GearDone := FALSE;
    bGearDone := FALSE;
  END_IF;
END_IF;
CASE nGearstate OF
  0:
  nGearstate := 0;
  1:
  g_T1GearIn.Execute := TRUE;
  g_T1GearIn.RatioNumerator := 1.0;
  g_T1GearIn.RatioDenominator := 1;
  IF g_T1GearIn.InGear THEN
    g_boGeneralAxis1GearDone := TRUE;
    g_bGeneralAxis1GearDone := TRUE;
    bGearDone := TRUE;
    bGearChuck := TRUE;
    nGearstate := 20;
    dCoordDiff := ABS(g_fiUCncCoord - g_General1_Axis.NCTOPLC.ACTPOS);
  END_IF;
  IF g_T1GearIn.ERROR OR g_T1GearIn.COMMANDABORTED THEN
    g_T1GearIn.Execute := FALSE;
    g_bGeneralAxis1GearInError := TRUE;
    nGearstate := 0;
  END_IF;
  2:
  g_T1GearOut.EXECUTE := TRUE;
  g_T1GearIn.EXECUTE := FALSE;
  IF g_T1GearOut.DONE THEN
    g_T1GearOut.EXECUTE := FALSE;
    IF g_General1_Axis.NCTOPLC.AXISSTATE = 2 THEN
      nGearstate := 0;
    ELSE
      nGearstate := 3;
    END_IF;
  END_IF;
  IF g_T1GearOut.ERROR THEN
    g_T1GearOut.EXECUTE := FALSE;
    g_bGeneralAxis1GearInError := TRUE;
      nGearState := 0;
      bGearChuck := FALSE;
    END_IF;
  3:
  g_General1_Stop.EXECUTE := TRUE;
  IF g_General1_Stop.DONE THEN
    g_General1_Stop.EXECUTE := FALSE;
    nGearstate := 0;
  END_IF;
  IF g_General1_Stop.COMMANDABORTED OR g_General1_Stop.ERROR THEN
    g_General1_Stop.EXECUTE := FALSE;
    nGearstate := 0;
  END_IF;
  20:
  IF g_General1_Axis.NCTOPLC.AXISSTATE = 8 THEN
    IF ABS(ABS(g_fiUCncCoord - g_General1_Axis.NCTOPLC.ACTPOS) - dCoordDiff) > dCoordMaxDiff AND g_General1_Axis.NCTOPLC.AXISSTATE = 8 THEN
      g_bGeneralAxis1GearInError := TRUE;
    END_IF;
  END_IF;
END_CASE;
